#!/usr/bin/env bash
set -e

echo "=== Preparing Deterministic Android Keystore ==="

# 1. Custom repository secrets (optional override)
if [ -n "$KEYSTORE_BASE64" ]; then
  echo "Found KEYSTORE_BASE64 environment variable, restoring custom key..."
  echo "$KEYSTORE_BASE64" | tr -d '\r\n ' | base64 -d > debug.keystore
elif [ -n "$SIGNING_KEYSTORE_BASE64" ]; then
  echo "Found SIGNING_KEYSTORE_BASE64 environment variable, restoring custom key..."
  echo "$SIGNING_KEYSTORE_BASE64" | tr -d '\r\n ' | base64 -d > debug.keystore
elif [ -f "debug.keystore.base64" ] && [ -s "debug.keystore.base64" ]; then
  echo "Restoring from workspace debug.keystore.base64..."
  tr -d '\r\n ' < debug.keystore.base64 | base64 -d > debug.keystore
else
  echo "Restoring from deterministic embedded project signing key..."
  cat << 'EOF' | tr -d '\r\n ' | base64 -d > debug.keystore

EOF
fi

# 4. Final verification
if [ ! -f debug.keystore ] || [ ! -s debug.keystore ]; then
  echo "Error: Keystore generation/restoration failed!"
  exit 1
fi

echo "Keystore successfully ready at debug.keystore"
